-- ===========================================================================
-- DEMONSTRATION DATA — DELETE BEFORE ANY REAL IMPORT
--
-- Generated by scripts/generate_demo_seed.mjs. Do not edit by hand: change
-- the generator and re-run it.
--
-- Every id begins '5eed0000', which is how
-- supabase/seed/999_placeholder_teardown.sql finds this data and nothing else.
--
-- NO REAL CHILD APPEARS HERE. Every name is generated. The only thing taken
-- from the centre is the chess curriculum for levels 1-3, which is not
-- personal data. Level 4's topics are invented -- their own system holds
-- twelve unnamed placeholder slots, so there was nothing real to copy.
--
-- A term of classes is simulated in order, so the data is internally
-- consistent: a student is only ahead on topics their class actually
-- covered, and the history explains the grid.
-- 86 students · 837 progress rows · 74 classes · 1296 history entries
-- Including 5 children who left an older page behind on a level they
-- finished, so the tidy-up screen has something real to work through.
-- ===========================================================================

begin;

-- Triggers off: the blank-row trigger would race the statuses below, and
-- the history trigger would stamp every event with the moment of the seed
-- rather than the date it is meant to have happened.
set local session_replication_role = replica;

-- Programmes -----------------------------------------------------------
-- Chess already exists (migration 0010); only the second one is demo data.

-- Levels and topics ----------------------------------------------------

-- Students and enrollments ---------------------------------------------

-- Where the term left everyone -----------------------------------------

-- The timetable --------------------------------------------------------

-- Classes that happened ------------------------------------------------

-- How everyone got there -----------------------------------------------

-- Triggers back on, then the blanks ------------------------------------
set local session_replication_role = origin;

-- A blank row for every topic nobody has touched yet, so each grid renders
-- a full row. This writes no history: a blank is the absence of it.
select public.ensure_progress_rows(id) from students;

-- Four weeks of classes ahead, so the demo always has one to open. The
-- simulation above only plays out the past; without this the Today page
-- greets a visitor with nothing.
select public.generate_all_series((current_date + 28)::date);

commit;
